text:
/* Override the legacy global table minimum width for the responsive history grid. */
.table {
  min-width: 0;
}

.root {
  --h-surface: var(--color-history-h-surface-1);
  --h-text: var(--color-history-h-text-2);
  --h-muted: var(--color-history-h-muted-3);
  --h-border: var(--color-history-h-border-4);
  --h-purple: var(--color-history-h-purple-5);
  --h-pink: var(--color-history-h-pink-6);
  --h-green: var(--color-history-h-green-7);
  --h-yellow: var(--status-warning-text);
  --h-inset: var(--color-history-h-inset-8);
}
:global([data-theme="dark"]) .root {
  --h-surface: var(--color-history-h-surface-9);
  --h-text: var(--color-history-h-text-10);
  --h-muted: var(--color-history-h-muted-11);
  --h-border: var(--color-history-h-border-12);
  --h-purple: var(--color-history-h-purple-13);
  --h-pink: var(--color-history-h-pink-14);
  --h-green: var(--color-history-h-green-15);
  --h-yellow: var(--color-history-h-yellow-16);
  --h-inset: var(--color-history-h-inset-17);
}
.root :is(button, a, input, [tabindex]):focus-visible {
  outline: 2px solid var(--appearance-focus, var(--h-pink));
  outline-offset: 2px;
}
.pill b {
  color: var(--h-text);
}
.table thead,
.table tbody {
  display: block;
}
.row > :is(td, th) {
  min-width: 0;
  padding: 0;
  border: 0;
  text-align: left;
  overflow-wrap: anywhere;
}
.row:not(.heading):hover {
  background: var(--appearance-wash, var(--color-history-background-20));
}
@media (hover: hover) and (pointer: fine) {
  .actions .action:hover:not([aria-busy="true"]) {
    translate: 0 -2px;
    filter: var(--button-hover-filter);
    border-color: var(--appearance-border, var(--color-history-h-purple-13));
  }
  .actions .action:active:not([aria-disabled="true"]) {
    translate: 0 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .actions .action {
    translate: none !important;
  }
}
.empty td {
  display: block;
}
.pagination nav > span {
  color: var(--h-muted);
}
.pagination nav a {
  border-radius: 999px;
  border-color: var(--h-border);
  background: var(--h-surface);
  color: var(--h-text);
}
@media (max-width: 859px) {
  .table thead {
    display: none;
  }
  .row > td:nth-child(1) {
    grid-column: 1;
    grid-row: 1;
  }
  .row > td:nth-child(6) {
    grid-column: 2;
    grid-row: 1;
  }
  .row > td:nth-child(2),
  .row > td:nth-child(3),
  .row > td:nth-child(4),
  .row > td:nth-child(5) {
    grid-column: 1 / -1;
  }
}

:global(html[data-workspace][data-appearance="vercel"]) .root {
  --h-surface: var(--card);
  --h-text: var(--foreground);
  --h-muted: var(--body);
  --h-border: var(--border);
  --h-purple: var(--link);
  --h-pink: var(--ring);
  --h-green: var(--status-success-text);
  --h-yellow: var(--warning);
  --h-inset: var(--surface);
}
/* Thin progress arcs and segments need contrast against Chalk's light surface. */
:global(html[data-workspace][data-appearance="vercel"][data-theme="light"])
  .root {
  --queued: var(--status-warning-text);
}
:global(html[data-workspace][data-appearance="vercel"]) .eyebrow {
  color: var(--coral);
}

:global(html[data-workspace][data-appearance="vercel"])
  :is(.pill, .role, .badge, .template) {
  border-radius: var(--appearance-badge-radius);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.role, .company, .template) {
  background: var(--highlight-background);
  color: var(--highlight-foreground);
  border: 1px solid var(--highlight-border);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.chip, .search, .pagination nav a) {
  border-radius: var(--appearance-control-radius);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.company, .template) {
  display: inline-block;
  padding: 3px 9px;
  border-radius: var(--appearance-badge-radius);
}

:global(html[data-workspace][data-appearance="vercel"])
  .active:not([aria-disabled="true"]) {
  background: var(--highlight-background);
  color: var(--highlight-foreground);
  border-color: var(--highlight-border);
}

:global(html[data-workspace][data-appearance="vercel"]) .role {
  background: var(--history-role-background);
  color: var(--history-role-text);
  border-color: var(--history-role-border);
}
:global(html[data-workspace][data-appearance="vercel"]) .tile {
  box-shadow: inset 0 0 0 1px var(--workspace-icon-border);
}
:global(html[data-workspace][data-appearance="vercel"]) .avatar {
  background: var(--color-history-background-23);
  color: var(--color-history-color-24);
}
